# -*- coding: utf-8 -*-
"""Imagine-кадры второй половины ролика: n=2, отбор глазами. Железо новое и чистое, свет схемой, палитра с замком, 16:9."""
import sys, io, os, time, json
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "first5", "imagine"); os.makedirs(OUT, exist_ok=True)
import xai

CLEAN = "Всё железо новое, только с завода, безупречно чистое, без пыли и следов. "
P = {
 # переезд на B650: компактная простая плата крупно
 "f08_b650": "СУБЪЕКТ: макро компактной бюджетной материнской платы: чёрный текстолит, скромные низкие радиаторы питания без подсветки, простые слоты, никакой брони и декоративных кожухов. Никаких логотипов и надписей. " + CLEAN + "СВЕТ: строго один источник: холодный белый софтбокс слева сверху под сорок пять градусов, мягкий, 5600K, заполняющего света нет, правый край уходит в глубокую нейтральную тень. ПЕРЕДНИЙ ПЛАН: угол платы с крепёжным отверстием крупно и резко. СРЕДНИЙ ПЛАН: сокет и радиаторы. ДАЛЬНИЙ ПЛАН: тёмная столешница размыта до мягкой мути. ПАЛИТРА строго из трёх цветов и только из них: чёрный, графит, холодное серебро. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: макро под тридцать градусов, горизонтальный кадр 16:9. Фотография.",
 # CS2-акт: метафора «контре нужен кэш и чтобы не дёргали» — один процессор в тихой тёмной комнате
 "f09_quiet": "СЦЕНА: один процессор без крышки лежит в центре пустого тёмного стола, вокруг него аккуратный круг свободного пространства, дальше по краям стола в темноте угадываются отодвинутые лишние предметы. " + CLEAN + "СВЕТ: строго один источник: узкий холодный луч точно сверху, жёсткий, 5000K, круглое пятно света ровно на процессоре, заполняющего света нет, всё вокруг тонет в черноте. ПЕРЕДНИЙ ПЛАН: край стола тёмный. ДАЛЬНИЙ ПЛАН: чёрная пустота. ПАЛИТРА строго из трёх цветов и только из них: чёрный, холодное серебро, тёплая медь. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: средний план сверху под шестьдесят градусов, горизонтальный кадр 16:9. Фотография.",
 # тизер следующей серии: кристалл под лупой
 "f10_scope": "СУБЪЕКТ: большая круглая лабораторная лупа на штативе наведена на открытый кристалл процессора, сквозь стекло кристалл увеличен и блестит. " + CLEAN + "СВЕТ: строго один источник: холодный белый луч справа сверху под сорок пять градусов, жёсткий, 5600K, блик на стекле лупы, заполняющего света нет, фон уходит в чёрное. ПЕРЕДНИЙ ПЛАН: край стола из тёмного металла. ДАЛЬНИЙ ПЛАН: чёрная пустота с мягким бликом. ПАЛИТРА строго из трёх цветов и только из них: чёрный, холодное серебро, тёплая медь. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: средний план на уровне стола, лупа занимает правую половину кадра, горизонтальный кадр 16:9. Фотография.",
}
log = []
for key, prompt in P.items():
    t0 = time.time()
    try:
        paths = xai.image(prompt, os.path.join(OUT, key), n=2, aspect="16:9")
        log.append({"key": key, "files": paths, "sec": round(time.time() - t0)}); print(key, "OK", round(time.time() - t0), "с")
    except Exception as e:
        log.append({"key": key, "error": str(e)}); print(key, "ERR", e)
json.dump(log, open(os.path.join(OUT, "log2.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("done")
